package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20) // PIC X(20) len=20 = SPACES
var WsACount int64 = 0 // PIC 99 len=2 = 0
var WsTotalA int64 = 0 // PIC 999 len=3 = 0
var WsCount int64 = 0  // PIC 999 len=3 = 0

var CurRec PartRec

var partFile *os.File
var partScanner *bufio.Scanner

func MainPara() {
	var err error
	partFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	partScanner = bufio.NewScanner(partFile)
	partScanner.Buffer(make([]byte, 64*1024), 10*1024*1024)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	partFile.Close()
	partFile = nil
	SummaryPara()
}

func ReadPara() {
	if partScanner.Scan() {
		line := partScanner.Text()
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		CurRec.LbPart = line[0:8]
		CurRec.LbRegion = line[8:11]
		serialRaw := line[11:15]
		t := strings.TrimSpace(serialRaw)
		if t == "" {
			CurRec.LbSerial = 0
		} else {
			v, err := strconv.ParseInt(strings.TrimSpace(serialRaw), 10, 64)
			if err != nil {
				CurRec.LbSerial = 0
			} else {
				// keep low-order 4 digits
				mod := int64(10000)
				CurRec.LbSerial = ((v % mod) + mod) % mod
			}
		}
	} else {
		if err := partScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	cnt := strings.Count(CurRec.LbPart, "A")
	WsACount = int64(cnt) % 100

	regionPart := CurRec.LbRegion
	if idx := strings.IndexByte(regionPart, ' '); idx >= 0 {
		regionPart = regionPart[:idx]
	}
	partPart := CurRec.LbPart
	if idx := strings.IndexByte(partPart, ' '); idx >= 0 {
		partPart = partPart[:idx]
	}
	serialVal := ((CurRec.LbSerial % 10000) + 10000) % 10000
	serialPart := fmt.Sprintf("%04d", serialVal)

	tgt := make([]byte, 20)
	for i := range tgt {
		tgt[i] = ' '
	}
	pos := 0
	for _, src := range []string{regionPart, "-", partPart, "-", serialPart} {
		for i := 0; i < len(src); i++ {
			if pos >= 20 {
				break
			}
			tgt[pos] = src[i]
			pos++
		}
		if pos >= 20 {
			break
		}
	}
	WsLabel = string(tgt)
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000
	aStr := fmt.Sprintf("%02d", WsACount)
	fmt.Printf("%s A=%s\n", WsLabel, aStr)
	ReadPara()
}

func SummaryPara() {
	cStr := fmt.Sprintf("%03d", WsCount)
	tStr := fmt.Sprintf("%03d", WsTotalA)
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", cStr, tStr)
}

func main() {
	MainPara()
}
